import Foundation
import CoreGraphics
import AppKit

extension Holiday250Catalog {
    static func drawBatch4_191_to_250(ctx: CGContext, n: Int, s: CGFloat, col: NSColor, rawPrimary: NSColor, rim: NSColor, lit: Bool, broken: Bool) {
        let gold = shade(NSColor(srgbRed: 0.98, green: 0.78, blue: 0.16, alpha: 1), lit: lit)
        let orange = shade(NSColor(srgbRed: 0.96, green: 0.48, blue: 0.12, alpha: 1), lit: lit)
        let red = shade(NSColor(srgbRed: 0.88, green: 0.14, blue: 0.18, alpha: 1), lit: lit)
        let pink = shade(NSColor(srgbRed: 0.96, green: 0.42, blue: 0.68, alpha: 1), lit: lit)
        let green = shade(NSColor(srgbRed: 0.14, green: 0.68, blue: 0.24, alpha: 1), lit: lit)
        let blue = shade(NSColor(srgbRed: 0.22, green: 0.56, blue: 0.96, alpha: 1), lit: lit)
        let cyan = shade(NSColor(srgbRed: 0.22, green: 0.88, blue: 0.96, alpha: 1), lit: lit)
        let purple = shade(NSColor(srgbRed: 0.62, green: 0.24, blue: 0.88, alpha: 1), lit: lit)
        let white = shade(NSColor(srgbRed: 0.97, green: 0.97, blue: 0.99, alpha: 1), lit: lit, darkFraction: 0.42)
        let brown = shade(NSColor(srgbRed: 0.58, green: 0.34, blue: 0.16, alpha: 1), lit: lit)
        let silver = shade(NSColor(srgbRed: 0.80, green: 0.84, blue: 0.90, alpha: 1), lit: lit, darkFraction: 0.45)
        let bronze = shade(NSColor(srgbRed: 0.72, green: 0.45, blue: 0.22, alpha: 1), lit: lit)

        switch n {
        // Collection 20 — Thanksgiving (191..200)
        case 191: // Turkey (fanned autumn tail feathers + brown body + red wattle)
            for (i, c) in [red, orange, gold, orange, red].enumerated() {
                let a = CGFloat(i - 2) * 0.35
                ctx.saveGState(); ctx.translateBy(x: 16 * s, y: 19 * s); ctx.rotate(by: a)
                ctx.setFillColor(c.cgColor); ctx.fillEllipse(in: CGRect(x: -2.2 * s, y: -12 * s, width: 4.4 * s, height: 10 * s))
                ctx.restoreGState()
            }
            ctx.setFillColor(brown.cgColor); ctx.fillEllipse(in: CGRect(x: 10 * s, y: 15 * s, width: 12 * s, height: 11 * s)); ctx.fillEllipse(in: CGRect(x: 13 * s, y: 10 * s, width: 6 * s, height: 6 * s))
            ctx.setFillColor(red.cgColor); ctx.fill(CGRect(x: 16.5 * s, y: 13.5 * s, width: 2 * s, height: 3 * s))
        case 192: // Cornucopia (curved horn of plenty + colorful harvest spilling out)
            let horn = CGMutablePath(); horn.move(to: CGPoint(x: 6 * s, y: 13 * s)); horn.addQuadCurve(to: CGPoint(x: 26 * s, y: 18 * s), control: CGPoint(x: 18 * s, y: 9 * s)); horn.addLine(to: CGPoint(x: 22 * s, y: 26 * s)); horn.addQuadCurve(to: CGPoint(x: 6 * s, y: 13 * s), control: CGPoint(x: 12 * s, y: 25 * s))
            fillAndStroke(ctx, path: horn, fill: brown, stroke: rim, lineW: s)
            ctx.setFillColor(orange.cgColor); ctx.fillEllipse(in: CGRect(x: 19 * s, y: 17 * s, width: 6 * s, height: 6 * s))
            ctx.setFillColor(red.cgColor); ctx.fillEllipse(in: CGRect(x: 23 * s, y: 20 * s, width: 4.5 * s, height: 4.5 * s))
        case 193: // Pumpkin pie (triangular slice + crimped crust + whipped cream dollop)
            let pie = CGMutablePath(); pie.move(to: CGPoint(x: 16 * s, y: 8 * s)); pie.addLine(to: CGPoint(x: 6.5 * s, y: 24 * s)); pie.addLine(to: CGPoint(x: 25.5 * s, y: 24 * s)); pie.closeSubpath()
            fillAndStroke(ctx, path: pie, fill: orange, stroke: rim, lineW: s)
            ctx.setFillColor(gold.cgColor); ctx.fill(CGRect(x: 6.5 * s, y: 23 * s, width: 19 * s, height: 3.5 * s))
            ctx.setFillColor(white.cgColor); ctx.fillEllipse(in: CGRect(x: 13.5 * s, y: 15 * s, width: 5 * s, height: 4.5 * s))
        case 194: // Cranberry sprig (arched twig + ruby cranberries + leaves)
            ctx.setStrokeColor(brown.cgColor); ctx.setLineWidth(1.5 * s); ctx.move(to: CGPoint(x: 8 * s, y: 26 * s)); ctx.addQuadCurve(to: CGPoint(x: 24 * s, y: 8 * s), control: CGPoint(x: 14 * s, y: 16 * s)); ctx.strokePath()
            ctx.setFillColor(green.cgColor); ctx.fillEllipse(in: CGRect(x: 9 * s, y: 13 * s, width: 7 * s, height: 4 * s)); ctx.fillEllipse(in: CGRect(x: 17 * s, y: 16 * s, width: 7 * s, height: 4 * s))
            for (bx, by) in [(13, 21), (16, 15), (20, 11)] { ctx.setFillColor(red.cgColor); ctx.fillEllipse(in: CGRect(x: CGFloat(bx) * s, y: CGFloat(by) * s, width: 4 * s, height: 4 * s)) }
        case 195: // Autumn wreath (ring of red/orange/gold foliage + bow)
            ctx.setStrokeColor(orange.cgColor); ctx.setLineWidth(4.5 * s); ctx.strokeEllipse(in: CGRect(x: 7 * s, y: 8 * s, width: 18 * s, height: 18 * s))
            ctx.setFillColor(red.cgColor); ctx.fillEllipse(in: CGRect(x: 9 * s, y: 9 * s, width: 4 * s, height: 4 * s)); ctx.fillEllipse(in: CGRect(x: 19 * s, y: 9 * s, width: 4 * s, height: 4 * s))
            ctx.setFillColor(gold.cgColor); ctx.fillEllipse(in: CGRect(x: 14 * s, y: 23 * s, width: 4 * s, height: 4 * s))
        case 196: // Warm cider mug (spiced mug + cinnamon stick + steam wisps)
            ctx.setStrokeColor(white.withAlphaComponent(0.75).cgColor); ctx.setLineWidth(s)
            ctx.move(to: CGPoint(x: 13 * s, y: 11 * s)); ctx.addLine(to: CGPoint(x: 12 * s, y: 7 * s))
            ctx.move(to: CGPoint(x: 18 * s, y: 11 * s)); ctx.addLine(to: CGPoint(x: 19 * s, y: 7 * s)); ctx.strokePath()
            ctx.setStrokeColor(orange.cgColor); ctx.setLineWidth(2.2 * s); ctx.strokeEllipse(in: CGRect(x: 19 * s, y: 15 * s, width: 6 * s, height: 7 * s))
            ctx.setFillColor(orange.cgColor); ctx.fillRoundedRect(CGRect(x: 8 * s, y: 13 * s, width: 14 * s, height: 13 * s), xRadius: 2.5 * s, yRadius: 2.5 * s)
        case 197: // Decorated autumn plate (warm rimmed china + leaf emblem)
            let p = CGRect(x: 6.5 * s, y: 8.5 * s, width: 19 * s, height: 19 * s)
            ctx.setFillColor(white.cgColor); ctx.fillEllipse(in: p)
            ctx.setStrokeColor(gold.cgColor); ctx.setLineWidth(2 * s); ctx.strokeEllipse(in: p.insetBy(dx: 2 * s, dy: 2 * s))
            ctx.setFillColor(orange.cgColor); ctx.fillEllipse(in: CGRect(x: 12.5 * s, y: 14.5 * s, width: 7 * s, height: 7 * s))
        case 198: // Gratitude scroll (parchment roll + rolled ends + ribbon)
            ctx.setFillColor(shade(NSColor(srgbRed: 0.96, green: 0.88, blue: 0.68, alpha: 1), lit: lit).cgColor)
            ctx.fill(CGRect(x: 9 * s, y: 9 * s, width: 14 * s, height: 16 * s))
            ctx.setFillColor(gold.cgColor); ctx.fillRoundedRect(CGRect(x: 7 * s, y: 8 * s, width: 18 * s, height: 3.5 * s), xRadius: 1.5 * s, yRadius: 1.5 * s)
            ctx.fillRoundedRect(CGRect(x: 7 * s, y: 24 * s, width: 18 * s, height: 3.5 * s), xRadius: 1.5 * s, yRadius: 1.5 * s)
            ctx.setStrokeColor(brown.cgColor); ctx.move(to: CGPoint(x: 11 * s, y: 14 * s)); ctx.addLine(to: CGPoint(x: 20 * s, y: 14 * s)); ctx.move(to: CGPoint(x: 11 * s, y: 18 * s)); ctx.addLine(to: CGPoint(x: 19 * s, y: 18 * s)); ctx.strokePath()
        case 199: // Harvest candle (short ribbed autumn candle + brass tray + flame)
            ctx.setFillColor(gold.cgColor); ctx.fillEllipse(in: CGRect(x: 7 * s, y: 24 * s, width: 18 * s, height: 4.5 * s))
            ctx.setFillColor(col.cgColor); ctx.fill(CGRect(x: 11.5 * s, y: 13 * s, width: 9 * s, height: 12 * s))
            ctx.setFillColor(gold.cgColor); ctx.fillEllipse(in: CGRect(x: 14 * s, y: 7 * s, width: 4 * s, height: 5.5 * s))
        case 200: // Fall centerpiece (brass bowl filled with autumn leaves & candle)
            ctx.setFillColor(orange.cgColor); ctx.fillEllipse(in: CGRect(x: 8 * s, y: 13 * s, width: 16 * s, height: 8 * s))
            ctx.setFillColor(red.cgColor); ctx.fill(CGRect(x: 14.5 * s, y: 8 * s, width: 3 * s, height: 8 * s))
            ctx.setFillColor(brown.cgColor); ctx.fillEllipse(in: CGRect(x: 7 * s, y: 18 * s, width: 18 * s, height: 9 * s))

        // Collection 21 — New Year's Eve (201..210)
        case 201: // Firework (radiating multi-colored starburst rays)
            for i in 0..<8 {
                let a = CGFloat(i) * .pi / 4.0
                ctx.setStrokeColor((i % 2 == 0 ? col : gold).cgColor); ctx.setLineWidth(1.6 * s)
                ctx.move(to: CGPoint(x: 16 * s, y: 17 * s)); ctx.addLine(to: CGPoint(x: (16 + cos(a) * 10) * s, y: (17 + sin(a) * 10) * s)); ctx.strokePath()
                ctx.setFillColor(white.cgColor); ctx.fillEllipse(in: CGRect(x: (15 + cos(a) * 10) * s, y: (16 + sin(a) * 10) * s, width: 2.2 * s, height: 2.2 * s))
            }
        case 202: // Sparkling party glass (champagne flute + golden fizz bubbles)
            let cup = CGMutablePath(); cup.move(to: CGPoint(x: 11.5 * s, y: 8 * s)); cup.addLine(to: CGPoint(x: 20.5 * s, y: 8 * s)); cup.addLine(to: CGPoint(x: 17.5 * s, y: 18 * s)); cup.addLine(to: CGPoint(x: 14.5 * s, y: 18 * s)); cup.closeSubpath()
            fillAndStroke(ctx, path: cup, fill: col, stroke: white, lineW: s)
            ctx.setStrokeColor(white.cgColor); ctx.setLineWidth(1.5 * s); ctx.move(to: CGPoint(x: 16 * s, y: 18 * s)); ctx.addLine(to: CGPoint(x: 16 * s, y: 27 * s)); ctx.move(to: CGPoint(x: 11 * s, y: 27 * s)); ctx.addLine(to: CGPoint(x: 21 * s, y: 27 * s)); ctx.strokePath()
        case 203: // Midnight clock (Roman dial struck precisely at 12:00!)
            let clk = CGRect(x: 7 * s, y: 8 * s, width: 18 * s, height: 18 * s)
            ctx.setFillColor(white.cgColor); ctx.fillEllipse(in: clk)
            ctx.setStrokeColor(gold.cgColor); ctx.setLineWidth(1.6 * s); ctx.strokeEllipse(in: clk)
            ctx.setStrokeColor(NSColor.black.cgColor); ctx.setLineWidth(1.4 * s)
            ctx.move(to: CGPoint(x: 16 * s, y: 17 * s)); ctx.addLine(to: CGPoint(x: 16 * s, y: 10.5 * s)); ctx.strokePath()
        case 204: // NYE party horn (gold/silver striped noisemaker cone)
            let c = CGMutablePath(); c.move(to: CGPoint(x: 7 * s, y: 26 * s)); c.addLine(to: CGPoint(x: 20 * s, y: 9 * s)); c.addLine(to: CGPoint(x: 26 * s, y: 15 * s)); c.closeSubpath()
            fillAndStroke(ctx, path: c, fill: col, stroke: gold, lineW: 1.2 * s)
        case 205: // Silver star
            fillAndStroke(ctx, path: starPath(center: CGPoint(x: 16 * s, y: 17 * s), outerR: 11 * s, innerR: 4.5 * s, points: 5), fill: silver, stroke: white, lineW: s)
        case 206: // Golden star
            fillAndStroke(ctx, path: starPath(center: CGPoint(x: 16 * s, y: 17 * s), outerR: 11 * s, innerR: 4.5 * s, points: 5), fill: gold, stroke: white, lineW: s)
        case 207: // Sparkler (wand stick + bright starburst tip)
            ctx.setStrokeColor(silver.cgColor); ctx.setLineWidth(1.4 * s); ctx.move(to: CGPoint(x: 16 * s, y: 13 * s)); ctx.addLine(to: CGPoint(x: 16 * s, y: 29 * s)); ctx.strokePath()
            fillAndStroke(ctx, path: starPath(center: CGPoint(x: 16 * s, y: 12 * s), outerR: 8 * s, innerR: 2 * s, points: 8), fill: col, stroke: white, lineW: 0.7 * s)
        case 208: // Midnight moon (deep silver crescent on indigo sky orb)
            ctx.setFillColor(shade(NSColor(srgbRed: 0.12, green: 0.14, blue: 0.34, alpha: 1), lit: lit).cgColor); ctx.fillEllipse(in: CGRect(x: 6.5 * s, y: 8 * s, width: 19 * s, height: 19 * s))
            ctx.setFillColor(silver.cgColor); ctx.fillEllipse(in: CGRect(x: 9.5 * s, y: 10.5 * s, width: 11 * s, height: 12 * s))
            ctx.setFillColor(shade(NSColor(srgbRed: 0.12, green: 0.14, blue: 0.34, alpha: 1), lit: lit).cgColor); ctx.fillEllipse(in: CGRect(x: 13 * s, y: 10.5 * s, width: 9 * s, height: 11 * s))
        case 209: // Calendar page (tear-off wall sheet showing "31" / midnight red top header)
            let pg = CGRect(x: 8 * s, y: 8 * s, width: 16 * s, height: 18 * s)
            ctx.setFillColor(white.cgColor); ctx.fill(pg)
            ctx.setFillColor(red.cgColor); ctx.fill(CGRect(x: 8 * s, y: 8 * s, width: 16 * s, height: 5 * s))
            ctx.setStrokeColor(rim.cgColor); ctx.stroke(pg)
            ctx.setFillColor(NSColor.black.cgColor); ctx.fill(CGRect(x: 11 * s, y: 16 * s, width: 10 * s, height: 2.5 * s)); ctx.fill(CGRect(x: 13 * s, y: 20 * s, width: 6 * s, height: 2.5 * s))
        case 210: // Disco ball (faceted mirrored sphere w/ highlight grid)
            let b = CGRect(x: 7 * s, y: 8.5 * s, width: 18 * s, height: 18 * s)
            ctx.setFillColor(silver.cgColor); ctx.fillEllipse(in: b)
            ctx.setStrokeColor(white.cgColor); ctx.setLineWidth(0.8 * s)
            ctx.strokeEllipse(in: CGRect(x: 11.5 * s, y: 8.5 * s, width: 9 * s, height: 18 * s))
            ctx.move(to: CGPoint(x: 7 * s, y: 17.5 * s)); ctx.addLine(to: CGPoint(x: 25 * s, y: 17.5 * s)); ctx.strokePath()
            ctx.setFillColor(col.cgColor); ctx.fill(CGRect(x: 12 * s, y: 13 * s, width: 3 * s, height: 3 * s)); ctx.fill(CGRect(x: 17 * s, y: 19 * s, width: 3 * s, height: 3 * s))

        // Collection 22 — Celestial Lights (211..220)
        case 211: // Five-pointed star
            fillAndStroke(ctx, path: starPath(center: CGPoint(x: 16 * s, y: 17 * s), outerR: 11 * s, innerR: 4.5 * s, points: 5), fill: col, stroke: rim, lineW: s)
        case 212: // Crescent moon
            ctx.setFillColor(col.cgColor); ctx.fillEllipse(in: CGRect(x: 8 * s, y: 8 * s, width: 16 * s, height: 18 * s))
            ctx.saveGState(); ctx.setBlendMode(.clear); ctx.fillEllipse(in: CGRect(x: 14 * s, y: 7.5 * s, width: 13 * s, height: 16 * s)); ctx.restoreGState()
        case 213: // Full moon cratered
            ctx.setFillColor(white.cgColor); ctx.fillEllipse(in: CGRect(x: 7 * s, y: 8 * s, width: 18 * s, height: 18 * s))
            ctx.setFillColor(silver.cgColor)
            ctx.fillEllipse(in: CGRect(x: 10 * s, y: 12 * s, width: 4 * s, height: 4 * s)); ctx.fillEllipse(in: CGRect(x: 17 * s, y: 17 * s, width: 5 * s, height: 5 * s)); ctx.fillEllipse(in: CGRect(x: 15 * s, y: 10.5 * s, width: 3 * s, height: 3 * s))
        case 214: // Blue planet (cerulean ocean sphere w/ cloud bands)
            let pl = CGRect(x: 7 * s, y: 8.5 * s, width: 18 * s, height: 18 * s)
            ctx.setFillColor(blue.cgColor); ctx.fillEllipse(in: pl)
            ctx.setFillColor(green.cgColor); ctx.fillEllipse(in: CGRect(x: 10 * s, y: 12 * s, width: 6 * s, height: 6 * s)); ctx.fillEllipse(in: CGRect(x: 17 * s, y: 17 * s, width: 5 * s, height: 6 * s))
        case 215: // Comet (bright nucleus + diagonal streaming plasma tail)
            let tail = CGMutablePath(); tail.move(to: CGPoint(x: 10 * s, y: 23 * s)); tail.addLine(to: CGPoint(x: 24 * s, y: 8 * s)); tail.addLine(to: CGPoint(x: 15 * s, y: 25 * s)); tail.closeSubpath()
            fillAndStroke(ctx, path: tail, fill: col.withAlphaComponent(0.75), stroke: white, lineW: 0.7 * s)
            ctx.setFillColor(white.cgColor); ctx.fillEllipse(in: CGRect(x: 8 * s, y: 19 * s, width: 7 * s, height: 7 * s))
        case 216: // Nebula (swirling cosmic purple/cyan gas cloud + stars)
            ctx.setFillColor(purple.withAlphaComponent(0.85).cgColor); ctx.fillEllipse(in: CGRect(x: 6 * s, y: 10 * s, width: 18 * s, height: 14 * s))
            ctx.setFillColor(col.withAlphaComponent(0.75).cgColor); ctx.fillEllipse(in: CGRect(x: 10 * s, y: 12 * s, width: 14 * s, height: 10 * s))
            ctx.setFillColor(white.cgColor); ctx.fillEllipse(in: CGRect(x: 14.5 * s, y: 16 * s, width: 3 * s, height: 3 * s))
        case 217: // Ringed planet (Saturn sphere encircled by tilted elliptical ring)
            ctx.setFillColor(col.cgColor); ctx.fillEllipse(in: CGRect(x: 9.5 * s, y: 11 * s, width: 13 * s, height: 13 * s))
            ctx.saveGState(); ctx.translateBy(x: 16 * s, y: 17.5 * s); ctx.rotate(by: -0.35)
            ctx.setStrokeColor(gold.cgColor); ctx.setLineWidth(2.2 * s); ctx.strokeEllipse(in: CGRect(x: -11.5 * s, y: -3.2 * s, width: 23 * s, height: 6.4 * s))
            ctx.restoreGState()
        case 218: // Shooting star (glinting 4-pt star + streak arc)
            ctx.setStrokeColor(gold.cgColor); ctx.setLineWidth(2 * s); ctx.move(to: CGPoint(x: 6 * s, y: 25 * s)); ctx.addQuadCurve(to: CGPoint(x: 22 * s, y: 11 * s), control: CGPoint(x: 13 * s, y: 14 * s)); ctx.strokePath()
            fillAndStroke(ctx, path: starPath(center: CGPoint(x: 22 * s, y: 11 * s), outerR: 5 * s, innerR: 1.8 * s, points: 5), fill: col, stroke: white, lineW: 0.7 * s)
        case 219: // Constellation (Big Dipper shaped connected star nodes)
            let pts = [CGPoint(x: 6*s, y: 12*s), CGPoint(x: 11*s, y: 14*s), CGPoint(x: 15*s, y: 17*s), CGPoint(x: 17*s, y: 23*s), CGPoint(x: 24*s, y: 23*s), CGPoint(x: 25*s, y: 16*s), CGPoint(x: 16*s, y: 16*s)]
            ctx.setStrokeColor(col.cgColor); ctx.setLineWidth(s)
            for i in 0..<(pts.count - 1) { ctx.move(to: pts[i]); ctx.addLine(to: pts[i + 1]) }
            ctx.strokePath(); ctx.setFillColor(white.cgColor); for p in pts { ctx.fillEllipse(in: CGRect(x: p.x - 1.5*s, y: p.y - 1.5*s, width: 3*s, height: 3*s)) }
        case 220: // Radiant Sun (crimson-gold corona spikes + warm center disk)
            fillAndStroke(ctx, path: starPath(center: CGPoint(x: 16 * s, y: 17 * s), outerR: 11.5 * s, innerR: 7.5 * s, points: 10), fill: orange, stroke: gold, lineW: 0.8 * s)
            ctx.setFillColor(gold.cgColor); ctx.fillEllipse(in: CGRect(x: 10 * s, y: 11 * s, width: 12 * s, height: 12 * s))

        // Collection 23 — Animals (221..230)
        case 221: // Cat (triangular cat ears + whiskers + bright feline eyes)
            ctx.setFillColor(col.cgColor); ctx.fillEllipse(in: CGRect(x: 8.5 * s, y: 12 * s, width: 15 * s, height: 14 * s))
            let el = CGMutablePath(); el.move(to: CGPoint(x: 9 * s, y: 15 * s)); el.addLine(to: CGPoint(x: 10 * s, y: 7 * s)); el.addLine(to: CGPoint(x: 14.5 * s, y: 12.5 * s)); ctx.addPath(el); ctx.fillPath()
            let er = CGMutablePath(); er.move(to: CGPoint(x: 23 * s, y: 15 * s)); er.addLine(to: CGPoint(x: 22 * s, y: 7 * s)); er.addLine(to: CGPoint(x: 17.5 * s, y: 12.5 * s)); ctx.addPath(er); ctx.fillPath()
            ctx.setFillColor(gold.cgColor); ctx.fillEllipse(in: CGRect(x: 11.5 * s, y: 16 * s, width: 2.5 * s, height: 2.5 * s)); ctx.fillEllipse(in: CGRect(x: 18 * s, y: 16 * s, width: 2.5 * s, height: 2.5 * s))
        case 222: // Dog (floppy ears + snout + red collar)
            ctx.setFillColor(brown.cgColor)
            ctx.fillEllipse(in: CGRect(x: 6.5 * s, y: 12 * s, width: 5.5 * s, height: 11 * s)); ctx.fillEllipse(in: CGRect(x: 20 * s, y: 12 * s, width: 5.5 * s, height: 11 * s))
            ctx.fillEllipse(in: CGRect(x: 9.5 * s, y: 9 * s, width: 13 * s, height: 14 * s))
            ctx.setFillColor(NSColor.black.cgColor); ctx.fillEllipse(in: CGRect(x: 14.5 * s, y: 17.5 * s, width: 3 * s, height: 2.2 * s))
            ctx.setFillColor(red.cgColor); ctx.fill(CGRect(x: 11 * s, y: 23 * s, width: 10 * s, height: 2.5 * s))
        case 223: // Fox (pointed ears + bright orange face + white cheeks)
            let head = CGMutablePath(); head.move(to: CGPoint(x: 8 * s, y: 13 * s)); head.addLine(to: CGPoint(x: 11 * s, y: 7 * s)); head.addLine(to: CGPoint(x: 14 * s, y: 12 * s)); head.addLine(to: CGPoint(x: 18 * s, y: 12 * s)); head.addLine(to: CGPoint(x: 21 * s, y: 7 * s)); head.addLine(to: CGPoint(x: 24 * s, y: 13 * s)); head.addLine(to: CGPoint(x: 16 * s, y: 26 * s)); head.closeSubpath()
            fillAndStroke(ctx, path: head, fill: orange, stroke: rim, lineW: s)
            ctx.setFillColor(white.cgColor); ctx.fillEllipse(in: CGRect(x: 11 * s, y: 18 * s, width: 4 * s, height: 4 * s)); ctx.fillEllipse(in: CGRect(x: 17 * s, y: 18 * s, width: 4 * s, height: 4 * s))
        case 224: // Owl (plumage oval + feathered ear tufts + huge golden eyes)
            ctx.setFillColor(brown.cgColor); ctx.fillEllipse(in: CGRect(x: 9 * s, y: 9 * s, width: 14 * s, height: 18 * s))
            ctx.setFillColor(gold.cgColor); ctx.fillEllipse(in: CGRect(x: 10.5 * s, y: 12 * s, width: 5 * s, height: 5 * s)); ctx.fillEllipse(in: CGRect(x: 16.5 * s, y: 12 * s, width: 5 * s, height: 5 * s))
            ctx.setFillColor(NSColor.black.cgColor); ctx.fillEllipse(in: CGRect(x: 12.2 * s, y: 13.7 * s, width: 1.8 * s, height: 1.8 * s)); ctx.fillEllipse(in: CGRect(x: 18.2 * s, y: 13.7 * s, width: 1.8 * s, height: 1.8 * s))
        case 225: // Rabbit (round tail + hopping side silhouette)
            ctx.setFillColor(col.cgColor); ctx.fillEllipse(in: CGRect(x: 10 * s, y: 15 * s, width: 12 * s, height: 10 * s)); ctx.fillEllipse(in: CGRect(x: 17 * s, y: 10 * s, width: 7 * s, height: 7 * s))
            ctx.fillEllipse(in: CGRect(x: 17 * s, y: 5 * s, width: 3 * s, height: 7 * s)); ctx.fillEllipse(in: CGRect(x: 20 * s, y: 6 * s, width: 3 * s, height: 6 * s))
            ctx.setFillColor(white.cgColor); ctx.fillEllipse(in: CGRect(x: 7 * s, y: 19 * s, width: 4 * s, height: 4 * s))
        case 226: // Deer (tan stag head + multi-tine antlers)
            ctx.setStrokeColor(brown.cgColor); ctx.setLineWidth(1.4 * s)
            ctx.move(to: CGPoint(x: 13 * s, y: 13 * s)); ctx.addLine(to: CGPoint(x: 8 * s, y: 6 * s)); ctx.move(to: CGPoint(x: 10.5 * s, y: 9.5 * s)); ctx.addLine(to: CGPoint(x: 12.5 * s, y: 7 * s))
            ctx.move(to: CGPoint(x: 19 * s, y: 13 * s)); ctx.addLine(to: CGPoint(x: 24 * s, y: 6 * s)); ctx.move(to: CGPoint(x: 21.5 * s, y: 9.5 * s)); ctx.addLine(to: CGPoint(x: 19.5 * s, y: 7 * s)); ctx.strokePath()
            ctx.setFillColor(bronze.cgColor); ctx.fillEllipse(in: CGRect(x: 11 * s, y: 13 * s, width: 10 * s, height: 13 * s))
        case 227: // Dolphin (arching curved sea blue silhouette + dorsal fin)
            let dol = CGMutablePath(); dol.move(to: CGPoint(x: 6 * s, y: 22 * s)); dol.addQuadCurve(to: CGPoint(x: 26 * s, y: 18 * s), control: CGPoint(x: 16 * s, y: 6 * s)); dol.addQuadCurve(to: CGPoint(x: 6 * s, y: 22 * s), control: CGPoint(x: 16 * s, y: 15 * s)); fillAndStroke(ctx, path: dol, fill: blue, stroke: white, lineW: s)
        case 228: // Butterfly (vibrant iridescent Monarch-style wings)
            ctx.setFillColor(col.cgColor); ctx.fillEllipse(in: CGRect(x: 6 * s, y: 9 * s, width: 9 * s, height: 10 * s)); ctx.fillEllipse(in: CGRect(x: 17 * s, y: 9 * s, width: 9 * s, height: 10 * s))
            ctx.setFillColor(gold.cgColor); ctx.fillEllipse(in: CGRect(x: 8 * s, y: 18 * s, width: 7 * s, height: 7 * s)); ctx.fillEllipse(in: CGRect(x: 17 * s, y: 18 * s, width: 7 * s, height: 7 * s))
            ctx.setFillColor(NSColor.black.cgColor); ctx.fill(CGRect(x: 15 * s, y: 9 * s, width: 2 * s, height: 17 * s))
        case 229: // Hummingbird (emerald hovering bird + long needle beak + wing)
            ctx.setFillColor(col.cgColor); ctx.fillEllipse(in: CGRect(x: 10 * s, y: 14 * s, width: 10 * s, height: 9 * s)); ctx.fillEllipse(in: CGRect(x: 16 * s, y: 10 * s, width: 6 * s, height: 6 * s))
            ctx.setStrokeColor(gold.cgColor); ctx.setLineWidth(1.3 * s); ctx.move(to: CGPoint(x: 21 * s, y: 13 * s)); ctx.addLine(to: CGPoint(x: 27 * s, y: 11 * s)); ctx.strokePath()
            ctx.setFillColor(cyan.cgColor); ctx.fillEllipse(in: CGRect(x: 7 * s, y: 8 * s, width: 9 * s, height: 5 * s))
        case 230: // Turtle (domed hex shell + green head & 4 flippers)
            ctx.setFillColor(green.cgColor); ctx.fillEllipse(in: CGRect(x: 19 * s, y: 14 * s, width: 6 * s, height: 5 * s))
            ctx.fill(CGRect(x: 9 * s, y: 21 * s, width: 4 * s, height: 5 * s)); ctx.fill(CGRect(x: 16 * s, y: 21 * s, width: 4 * s, height: 5 * s))
            ctx.setFillColor(brown.cgColor); ctx.fillEllipse(in: CGRect(x: 7 * s, y: 11 * s, width: 15 * s, height: 11 * s))

        // Collection 24 — Flowers and Plants (231..240)
        case 231: // Rose
            ctx.setStrokeColor(green.cgColor); ctx.setLineWidth(2 * s); ctx.move(to: CGPoint(x: 16 * s, y: 18 * s)); ctx.addLine(to: CGPoint(x: 16 * s, y: 29 * s)); ctx.strokePath()
            ctx.setFillColor(col.cgColor); ctx.fillEllipse(in: CGRect(x: 9.5 * s, y: 8 * s, width: 13 * s, height: 12 * s))
            ctx.setStrokeColor(white.withAlphaComponent(0.6).cgColor); ctx.strokeEllipse(in: CGRect(x: 12.5 * s, y: 11 * s, width: 7 * s, height: 6 * s))
        case 232: // Sunflower (ring of sunny golden petals + brown seed core)
            for i in 0..<10 {
                let a = CGFloat(i) * (2.0 * .pi / 10.0)
                ctx.setFillColor(gold.cgColor); ctx.fillEllipse(in: CGRect(x: (14 + cos(a) * 6.5) * s, y: (15 + sin(a) * 6.5) * s, width: 4.5 * s, height: 4.5 * s))
            }
            ctx.setFillColor(brown.cgColor); ctx.fillEllipse(in: CGRect(x: 11.5 * s, y: 12.5 * s, width: 9 * s, height: 9 * s))
        case 233: // Lavender (spike of fragrant violet buds)
            ctx.setStrokeColor(green.cgColor); ctx.setLineWidth(1.6 * s); ctx.move(to: CGPoint(x: 16 * s, y: 10 * s)); ctx.addLine(to: CGPoint(x: 16 * s, y: 29 * s)); ctx.strokePath()
            ctx.setFillColor(purple.cgColor)
            for row in 0..<5 { ctx.fillEllipse(in: CGRect(x: 13 * s, y: CGFloat(7 + row * 3) * s, width: 3.2 * s, height: 3.2 * s)); ctx.fillEllipse(in: CGRect(x: 16 * s, y: CGFloat(7 + row * 3) * s, width: 3.2 * s, height: 3.2 * s)) }
        case 234: // Orchid (wide lateral wings + vibrant speckled lip)
            ctx.setFillColor(col.cgColor); ctx.fillEllipse(in: CGRect(x: 6.5 * s, y: 11 * s, width: 9 * s, height: 8 * s)); ctx.fillEllipse(in: CGRect(x: 16.5 * s, y: 11 * s, width: 9 * s, height: 8 * s)); ctx.fillEllipse(in: CGRect(x: 12 * s, y: 7 * s, width: 8 * s, height: 8 * s))
            ctx.setFillColor(purple.cgColor); ctx.fillEllipse(in: CGRect(x: 12 * s, y: 16 * s, width: 8 * s, height: 9 * s))
        case 235: // Lily (6 pointed star blossom petals + stamens)
            fillAndStroke(ctx, path: starPath(center: CGPoint(x: 16 * s, y: 17 * s), outerR: 11 * s, innerR: 4 * s, points: 6), fill: col, stroke: rim, lineW: 0.9 * s)
            ctx.setFillColor(gold.cgColor); ctx.fillEllipse(in: CGRect(x: 14 * s, y: 15 * s, width: 4 * s, height: 4 * s))
        case 236: // Fern (graceful arched green frond leaflets)
            ctx.setStrokeColor(green.cgColor); ctx.setLineWidth(1.8 * s); ctx.move(to: CGPoint(x: 12 * s, y: 28 * s)); ctx.addQuadCurve(to: CGPoint(x: 20 * s, y: 7 * s), control: CGPoint(x: 12 * s, y: 14 * s)); ctx.strokePath()
            ctx.setFillColor(green.cgColor)
            for row in 0..<5 { let y = CGFloat(10.0 + Double(row) * 3.5) * s; ctx.fillEllipse(in: CGRect(x: 8 * s, y: y, width: 6 * s, height: 2.2 * s)); ctx.fillEllipse(in: CGRect(x: 16 * s, y: y, width: 7 * s, height: 2.2 * s)) }
        case 237: // Ivy (triangular 3-lobed deep emerald trailing leaf)
            let iv = CGMutablePath(); iv.move(to: CGPoint(x: 16 * s, y: 27 * s)); iv.addLine(to: CGPoint(x: 7 * s, y: 18 * s)); iv.addLine(to: CGPoint(x: 11 * s, y: 10 * s)); iv.addLine(to: CGPoint(x: 16 * s, y: 14 * s)); iv.addLine(to: CGPoint(x: 21 * s, y: 10 * s)); iv.addLine(to: CGPoint(x: 25 * s, y: 18 * s)); iv.closeSubpath()
            fillAndStroke(ctx, path: iv, fill: green, stroke: rim, lineW: s)
        case 238: // Flowering Cactus (terracotta pot + saguaro + blooming top flower)
            ctx.setFillColor(bronze.cgColor); ctx.fill(CGRect(x: 11 * s, y: 21 * s, width: 10 * s, height: 7 * s))
            ctx.setFillColor(green.cgColor); ctx.fillRoundedRect(CGRect(x: 13 * s, y: 10 * s, width: 6 * s, height: 12 * s), xRadius: 3 * s, yRadius: 3 * s)
            ctx.fillRoundedRect(CGRect(x: 8 * s, y: 13 * s, width: 5 * s, height: 3 * s), xRadius: 1.5 * s, yRadius: 1.5 * s)
            ctx.setFillColor(col.cgColor); ctx.fillEllipse(in: CGRect(x: 13.5 * s, y: 6.5 * s, width: 5 * s, height: 4.5 * s))
        case 239: // Succulent (concentric overlapping emerald lotus rosette)
            for rad in [10.0, 6.5, 3.2] {
                ctx.setFillColor((rad == 3.2 ? col : green).cgColor)
                ctx.fillEllipse(in: CGRect(x: CGFloat(16 - rad) * s, y: CGFloat(17 - rad) * s, width: CGFloat(rad * 2) * s, height: CGFloat(rad * 2) * s))
                ctx.setStrokeColor(rim.cgColor); ctx.setLineWidth(0.7 * s)
                ctx.strokeEllipse(in: CGRect(x: CGFloat(16 - rad) * s, y: CGFloat(17 - rad) * s, width: CGFloat(rad * 2) * s, height: CGFloat(rad * 2) * s))
            }
        case 240: // Cherry Blossom Branch (diagonal brown twig + 3 pink blossoms)
            ctx.setStrokeColor(brown.cgColor); ctx.setLineWidth(2 * s); ctx.move(to: CGPoint(x: 6 * s, y: 24 * s)); ctx.addLine(to: CGPoint(x: 25 * s, y: 10 * s)); ctx.strokePath()
            for (bx, by) in [(10, 18), (16, 14), (21, 12)] { ctx.setFillColor(pink.cgColor); ctx.fillEllipse(in: CGRect(x: CGFloat(bx - 3) * s, y: CGFloat(by - 3) * s, width: 6 * s, height: 6 * s)) }

        // Collection 25 — Retro & Novelty Lighting (241..250)
        case 241: // Vintage Marquee Bulb (brass sign socket + warm globe w/ dots)
            ctx.setFillColor(gold.cgColor); ctx.fill(CGRect(x: 11 * s, y: 5 * s, width: 10 * s, height: 5 * s))
            ctx.setFillColor(col.cgColor); ctx.fillEllipse(in: CGRect(x: 8 * s, y: 10 * s, width: 16 * s, height: 16 * s))
            ctx.setStrokeColor(gold.cgColor); ctx.setLineWidth(1.5 * s); ctx.strokeEllipse(in: CGRect(x: 8 * s, y: 10 * s, width: 16 * s, height: 16 * s))
        case 242: // Arcade Pixel Light (chunky 8-bit stepped pixel heart/gem)
            ctx.setFillColor(col.cgColor)
            ctx.fill(CGRect(x: 10 * s, y: 10 * s, width: 12 * s, height: 12 * s))
            ctx.fill(CGRect(x: 13 * s, y: 7 * s, width: 6 * s, height: 18 * s))
            ctx.fill(CGRect(x: 7 * s, y: 13 * s, width: 18 * s, height: 6 * s))
            ctx.setFillColor(white.cgColor); ctx.fill(CGRect(x: 11 * s, y: 11 * s, width: 3 * s, height: 3 * s))
        case 243: // Eight-Bit Star (blocky retro video-game power star w/ eyes!)
            ctx.setFillColor(col.cgColor)
            ctx.fill(CGRect(x: 13 * s, y: 6 * s, width: 6 * s, height: 21 * s))
            ctx.fill(CGRect(x: 6 * s, y: 12 * s, width: 20 * s, height: 6 * s))
            ctx.fill(CGRect(x: 9 * s, y: 18 * s, width: 5 * s, height: 9 * s)); ctx.fill(CGRect(x: 18 * s, y: 18 * s, width: 5 * s, height: 9 * s))
            ctx.setFillColor(NSColor.black.cgColor); ctx.fill(CGRect(x: 13.5 * s, y: 13 * s, width: 1.5 * s, height: 4 * s)); ctx.fill(CGRect(x: 17 * s, y: 13 * s, width: 1.5 * s, height: 4 * s))
        case 244: // CRT Glow (tiny retro TV monitor glowing on screen!)
            ctx.setFillColor(NSColor.darkGray.cgColor); ctx.fillRoundedRect(CGRect(x: 6 * s, y: 9 * s, width: 20 * s, height: 17 * s), xRadius: 3 * s, yRadius: 3 * s)
            ctx.setFillColor(col.cgColor); ctx.fillRoundedRect(CGRect(x: 8.5 * s, y: 11.5 * s, width: 13 * s, height: 11 * s), xRadius: 2 * s, yRadius: 2 * s)
            ctx.setFillColor(white.cgColor); ctx.fill(CGRect(x: 22.5 * s, y: 13 * s, width: 2 * s, height: 2 * s)); ctx.fill(CGRect(x: 22.5 * s, y: 17 * s, width: 2 * s, height: 2 * s))
        case 245: // Neon Tube (bright glowing U-shaped neon light sign)
            let neo = CGMutablePath(); neo.move(to: CGPoint(x: 10 * s, y: 8 * s)); neo.addLine(to: CGPoint(x: 10 * s, y: 21 * s)); neo.addArc(center: CGPoint(x: 16 * s, y: 21 * s), radius: 6 * s, startAngle: .pi, endAngle: 0, clockwise: true); neo.addLine(to: CGPoint(x: 22 * s, y: 8 * s))
            ctx.addPath(neo); ctx.setStrokeColor(col.cgColor); ctx.setLineWidth(3.6 * s); ctx.strokePath()
            ctx.addPath(neo); ctx.setStrokeColor(white.cgColor); ctx.setLineWidth(1.2 * s); ctx.strokePath()
        case 246: // Prism LED (crystalline triangular prism refracting RGB band)
            let pr = CGMutablePath(); pr.move(to: CGPoint(x: 16 * s, y: 7 * s)); pr.addLine(to: CGPoint(x: 6.5 * s, y: 26 * s)); pr.addLine(to: CGPoint(x: 25.5 * s, y: 26 * s)); pr.closeSubpath()
            fillAndStroke(ctx, path: pr, fill: col, stroke: white, lineW: 1.2 * s)
            ctx.setFillColor(white.withAlphaComponent(0.65).cgColor); ctx.fill(CGRect(x: 15 * s, y: 12 * s, width: 2 * s, height: 12 * s))
        case 247: // Stained-Glass Bulb (lead-came diamond mosaic dome)
            let b = CGRect(x: 8 * s, y: 9 * s, width: 16 * s, height: 18 * s)
            ctx.setFillColor(col.cgColor); ctx.fillEllipse(in: b)
            ctx.setStrokeColor(NSColor.black.cgColor); ctx.setLineWidth(1.2 * s)
            ctx.strokeEllipse(in: b); ctx.move(to: CGPoint(x: 16 * s, y: 9 * s)); ctx.addLine(to: CGPoint(x: 16 * s, y: 27 * s)); ctx.move(to: CGPoint(x: 8 * s, y: 18 * s)); ctx.addLine(to: CGPoint(x: 24 * s, y: 18 * s)); ctx.strokePath()
        case 248: // Steampunk Filament (copper rivets + visible glowing coil spiral)
            ctx.setFillColor(bronze.cgColor); ctx.fill(CGRect(x: 11 * s, y: 5.5 * s, width: 10 * s, height: 5 * s))
            ctx.setStrokeColor(bronze.cgColor); ctx.setLineWidth(1.5 * s); ctx.strokeEllipse(in: CGRect(x: 8.5 * s, y: 10.5 * s, width: 15 * s, height: 17 * s))
            ctx.setStrokeColor(gold.cgColor); ctx.setLineWidth(1.4 * s); ctx.strokeEllipse(in: CGRect(x: 12.5 * s, y: 14.5 * s, width: 7 * s, height: 7 * s))
        case 249: // Copper Edison Bulb (amber vintage teardrop glass + hair-pin filament)
            ctx.setFillColor(bronze.cgColor); ctx.fill(CGRect(x: 12 * s, y: 5 * s, width: 8 * s, height: 5.5 * s))
            ctx.setFillColor(orange.withAlphaComponent(0.55).cgColor); ctx.fillEllipse(in: CGRect(x: 9 * s, y: 10.5 * s, width: 14 * s, height: 18 * s))
            ctx.setStrokeColor(gold.cgColor); ctx.setLineWidth(1.3 * s); ctx.move(to: CGPoint(x: 14 * s, y: 11 * s)); ctx.addLine(to: CGPoint(x: 16 * s, y: 22 * s)); ctx.addLine(to: CGPoint(x: 18 * s, y: 11 * s)); ctx.strokePath()
        default: // 250: Fiber-Optic Sparkle (silver cone base + fanning lit fiber tips)
            ctx.setFillColor(silver.cgColor); ctx.fill(CGRect(x: 13 * s, y: 5.5 * s, width: 6 * s, height: 5.5 * s))
            for i in -3...3 {
                let ex = (16.0 + Double(i) * 3.2) * Double(s)
                let ey = (26.0 - Double(abs(i)) * 1.2) * Double(s)
                ctx.setStrokeColor(col.withAlphaComponent(0.8).cgColor); ctx.setLineWidth(1.1 * s)
                ctx.move(to: CGPoint(x: 16 * s, y: 11 * s)); ctx.addLine(to: CGPoint(x: ex, y: ey)); ctx.strokePath()
                ctx.setFillColor(white.cgColor); ctx.fillEllipse(in: CGRect(x: CGFloat(ex) - s, y: CGFloat(ey) - s, width: 2 * s, height: 2 * s))
            }
        }
    }
}

private extension CGContext {
    func fillRoundedRect(_ rect: CGRect, xRadius: CGFloat, yRadius: CGFloat) {
        let p = CGPath(roundedRect: rect, cornerWidth: xRadius, cornerHeight: yRadius, transform: nil)
        addPath(p)
        fillPath()
    }
}
